"""Self-generated byte transcripts only. No USB, archive code or real bodies."""
import hashlib
from pathlib import Path
import struct
import subprocess
import sys
from types import SimpleNamespace
import unittest
from unittest.mock import patch

from lutphoto import captureprotocol as p
from lutphoto.capturestore import Budget, Sink


def transcript(raw, *, seq=1, pfunc=0x40, response=0, fragments=None, drain=b''):
    """Independent peer fixture following pinned PMCA read boundaries."""
    out = []
    for start in range(0, max(1, len(raw)), 0x100000):
        rest = raw[start:]
        out.append(('header', struct.pack('<IHH4B', len(rest), pfunc, seq, 0, 0, 0, response)))
        frame = rest[:0x100000]
        for at in range(0, len(frame), 0x8000):
            block = frame[at:at + 0x8000]
            size = fragments or len(block)
            out.extend(('data', block[n:n + size]) for n in range(0, len(block), size))
            if len(block) % 0x200 == 0:
                out.append(('drain', drain))
    return out


def deliver(channel, records):
    result = None
    for kind, raw in records:
        expected = channel.next_read()
        if expected.kind != kind:
            raise AssertionError((expected.kind, kind))
        result = channel.feed(raw)
    return result


class ProtocolTests(unittest.TestCase):
    def setUp(self):
        self.clock = [0.0]
        self.budget = Budget(10 * 1024 * 1024, clock=lambda: self.clock[0])
        self.stock = SimpleNamespace(kind='stock', ap_bytes=2 * p.FRAME, cp_bytes=1024)
        self.policy = SimpleNamespace(sources=(self.stock,))
        self.loader = patch.object(p.workercontracts, 'load_sources', return_value=({}, {})).start()
        patch.object(p.programidentity, '_load_policy', return_value=self.policy).start()
        self.addCleanup(patch.stopall)
        self.c = p.OfflineChannel('not-a-real-archive', resources=True, budget=self.budget)

    def sink(self, name):
        spec = self.c.requests[name]
        return Sink(spec.limit, exact=spec.exact, budget=self.budget)

    def begin(self, name='ram'):
        sink = self.sink(name)
        self.c.begin(name, sink)
        return sink

    def select(self, name='cpapp-b.bin'):
        self.c.begin('select:' + name)
        deliver(self.c, transcript(bytes(4), seq=self.c.sequence))

    def assert_unknown(self):
        self.assertTrue(self.c.unknown)
        self.assertFalse(self.c.active)
        self.assertIsNone(self.c.result)
        with self.assertRaises(RuntimeError): self.c.claim_exit()
        with self.assertRaises(RuntimeError): self.c.begin('saved', self.sink('saved'))

    def assert_healthy_exit_once(self):
        self.assertFalse(self.c.unknown)
        self.c.claim_exit()
        with self.assertRaises(RuntimeError): self.c.claim_exit()
        with self.assertRaises(RuntimeError): self.c.begin('saved', self.sink('saved'))

    def test_source_pins_loaded_without_running_archive(self):
        self.loader.assert_called_once_with('not-a-real-archive', inventory=p.workercontracts.ROOT / 'research/upstream-backup-loader.lock.json')

    def test_golden_request_bytes(self):
        packet = self.c.begin('hasp', self.sink('hasp'))
        self.assertEqual(packet.hex(), '05000000100001000000000000001f0000')
        self.assertEqual(self.c.requests['ram'].data.hex(), '0306050001')
        self.assertEqual(self.c.requests['saved'].data.hex(), '0306050000')
        self.assertEqual(self.c.requests['read:appFw.so'].data.hex(), '0110110000ff00')
        self.assertEqual(self.c.requests['select:appFw.so'].data,
            b'\x01\x10\x0f\x00\x00/tmp/jiritsu/../../usr/lib/appFw.so\x00')
        self.assertEqual(self.c.requests['select:cpapp-b.bin'].data,
            b'\x01\x10\x0f\x00\x00/tmp/jiritsu/../../cp/cpapp-b.bin\x00')

    def test_resource_whitelist_and_frozen_requests(self):
        self.assertEqual(len(self.c.requests), 3 + 2 * 70)
        for n in p.customcontracts.RESOURCE_FILES:
            self.assertIn(b'/usr/share/app/' + n.encode() + b'\0', self.c.requests['select:' + n].data)
        with self.assertRaises(TypeError): self.c.requests['other'] = 1
        with self.assertRaises(AttributeError): self.c.requests['ram'].limit = 1
        c = p.OfflineChannel('dummy', budget=self.budget)
        self.assertEqual(len(c.requests), 7)

    def test_arbitrary_paths_commands_setters_forbidden(self):
        for name in ('/usr/lib/appFw.so', 'select:../../etc/passwd', 'read:libJit.so',
                     '16', '18', 'saveBackup', 'setBackupPresetData', 'writeMemory', '', None, 15):
            with self.subTest(name=name):
                c = p.OfflineChannel('dummy', budget=self.budget)
                with self.assertRaises(ValueError): c.begin(name)
                self.assertEqual(c.wire_bytes, 0)
                self.assertFalse(c.unknown)

    def test_no_identity_policy_or_path_override(self):
        for key in ('policy', 'serial', 'path', 'roles', 'driver'):
            with self.assertRaises(TypeError): p.OfflineChannel('dummy', **{key: 'arbitrary'})
        with self.assertRaises(ValueError): p.OfflineChannel('dummy', resources=1)

    def test_select_before_read_and_matching_file(self):
        with self.assertRaises(ValueError): self.c.begin('read:cpapp-b.bin', self.sink('read:cpapp-b.bin'))
        self.assert_healthy_exit_once()

    def test_wrong_selected_file_rejected_before_request(self):
        self.select('appFw.so')
        before = self.c.wire_bytes
        with self.assertRaises(ValueError): self.c.begin('read:cpapp-b.bin', self.sink('read:cpapp-b.bin'))
        self.assertEqual(self.c.wire_bytes, before)
        self.assert_healthy_exit_once()

    def test_select_read_status_stripped_and_no_implicit_repeat(self):
        self.select()
        sink = self.begin('read:cpapp-b.bin')
        raw = bytes(4) + b'a' * 1024
        result = deliver(self.c, transcript(raw, seq=2, fragments=3))
        self.assertEqual(result['payload'], {'bytes': 1024, 'sha256': hashlib.sha256(b'a' * 1024).hexdigest()})
        self.assertEqual(self.budget.used, 1024)
        self.assertTrue(sink.closed)
        self.assertIsNone(self.c.selected)
        with self.assertRaises(ValueError): self.c.begin('read:cpapp-b.bin', self.sink('read:cpapp-b.bin'))

    def test_fragmented_data_and_nonzero_separate_drain(self):
        sink = self.begin()
        raw = b'q' * (p.BLOCK + 512)
        records = transcript(raw, fragments=101, drain=b'not-assumed-zero')
        result = deliver(self.c, records)
        self.assertEqual(result['payload']['sha256'], hashlib.sha256(raw).hexdigest())
        self.assertEqual(sink.size, len(raw))
        request_len = 12 + 5
        self.assertEqual(self.c.wire_bytes, request_len + sum(len(raw) for _, raw in records))
        self.assertEqual(self.budget.used, len(raw))
        self.assertFalse(result['physical_protocol_verified'])
        self.assertFalse(result['response_profile_verified'])
        self.assertFalse(result['camera_operations_performed'])

    def test_zero_length_drain_is_valid_distinct_result(self):
        self.begin()
        deliver(self.c, transcript(b'z' * 512))
        self.assert_healthy_exit_once()

    def test_multiframe_response_and_single_sequence(self):
        sink = self.begin()
        raw = b'x' * (p.FRAME + 512)
        result = deliver(self.c, transcript(raw, drain=b'D' * 512))
        self.assertEqual(result['frames'], 2)
        self.assertEqual(sink.size, len(raw))
        self.assertEqual(self.c.sequence, 2)
        self.assert_healthy_exit_once()

    def test_no_unproven_monotonic_remaining_size_rule(self):
        self.begin()
        records = transcript(b'z' * (2 * p.FRAME + 1))
        for i, (kind, raw) in enumerate(records):
            if kind == 'header' and struct.unpack_from('<I', raw)[0] > p.FRAME:
                records[i] = (kind, struct.pack('<I', 3 * p.FRAME) + raw[4:])
        deliver(self.c, records)
        self.assertFalse(self.c.unknown)

    def test_product_response_one_and_exact_length(self):
        self.begin('hasp')
        result = deliver(self.c, transcript(b'H' * 88, pfunc=0x10, response=1))
        self.assertEqual(result['payload']['bytes'], 88)

    def test_complete_bad_status_is_known_but_blocks_new_reads(self):
        self.c.begin('select:cpapp-b.bin')
        with self.assertRaises(p.CompleteResponseError): deliver(self.c, transcript(struct.pack('<I', 0x10000006)))
        self.assertIsNone(self.c.selected)
        with self.assertRaises(RuntimeError): self.begin()
        self.assert_healthy_exit_once()

    def test_complete_short_status_is_known(self):
        self.c.begin('select:cpapp-b.bin')
        with self.assertRaises(p.CompleteResponseError): deliver(self.c, transcript(b'\0\0'))
        self.assert_healthy_exit_once()

    def test_complete_response_code_error_is_known(self):
        self.begin('hasp')
        with self.assertRaises(p.CompleteResponseError): deliver(self.c, transcript(b'H' * 88, pfunc=0x10, response=0))
        self.assert_healthy_exit_once()

    def test_complete_short_program_or_empty_snapshot_is_known(self):
        self.select()
        self.begin('read:cpapp-b.bin')
        with self.assertRaises(p.CompleteResponseError): deliver(self.c, transcript(bytes(4) + b'a', seq=2))
        self.assert_healthy_exit_once()
        c = p.OfflineChannel('dummy', budget=self.budget)
        spec = c.requests['ram']; c.begin('ram', Sink(spec.limit, budget=self.budget))
        with self.assertRaises(p.CompleteResponseError): deliver(c, transcript(b''))
        self.assertFalse(c.unknown)
        c.claim_exit()

    def test_short_header_unknown_not_accumulated(self):
        self.begin()
        with self.assertRaises(ValueError): self.c.feed(bytes(6))
        self.assert_unknown()

    def test_wrong_sequence_and_unverified_header_profile_stop(self):
        for field, value in ((1, 0x10), (2, 2), (3, 1), (4, 1), (5, 1)):
            with self.subTest(field=field):
                self.c = p.OfflineChannel('dummy', budget=self.budget)
                sink = self.begin()
                header = [1, 0x40, 1, 0, 0, 0, 0]; header[field] = value
                with self.assertRaises(ValueError): self.c.feed(struct.pack('<IHH4B', *header))
                self.assertEqual(sink.size, 0)
                self.assert_unknown()

    def test_declared_size_rejected_before_body(self):
        sink = self.begin('hasp')
        with self.assertRaises(ValueError): self.c.feed(struct.pack('<IHH4B', 0xffffffff, 0x10, 1, 0, 0, 0, 1))
        self.assertEqual(sink.size, 0)
        self.assert_unknown()

    def test_cumulative_continuations_bounded(self):
        self.select('appFw.so')
        sink = self.begin('read:appFw.so')
        raw = bytes(4) + b'p' * (2 * p.FRAME)
        records = transcript(raw, seq=2)
        # Replace the final 4-byte frame declaration with 5. Reject at header.
        last = max(i for i, (k, _) in enumerate(records) if k == 'header')
        records[last] = ('header', struct.pack('<IHH4B', 5, 0x40, 2, 0, 0, 0, 0))
        with self.assertRaises(ValueError): deliver(self.c, records[:last + 1])
        self.assertEqual(sink.size, 2 * p.FRAME - 4)
        self.assert_unknown()

    def test_global_payload_budget_rejected_before_body(self):
        self.budget.limit = 3
        sink = self.begin()
        with self.assertRaises(ValueError): self.c.feed(struct.pack('<IHH4B', 4, 0x40, 1, 0, 0, 0, 0))
        self.assertEqual(sink.size, 0)
        self.assertEqual(self.budget.used, 0)
        self.assert_unknown()

    def test_wire_budget_checks_before_scheduled_read(self):
        self.begin()
        self.c.wire_limit = self.c.wire_bytes + 11
        with self.assertRaises(ValueError): self.c.next_read()
        self.assert_unknown()

    def test_drain_counts_toward_wire_budget_not_payload(self):
        self.begin()
        records = transcript(b'd' * 512, drain=b'Q' * 512)
        deliver(self.c, records[:-1])
        self.assertEqual(self.budget.used, 512)
        self.c.wire_limit = self.c.wire_bytes + 511
        with self.assertRaises(ValueError): self.c.next_read()
        self.assert_unknown()

    def test_short_data_waits_and_abort_poisoned(self):
        sink = self.begin()
        self.c.feed(struct.pack('<IHH4B', 10, 0x40, 1, 0, 0, 0, 0))
        self.c.feed(b'a')
        self.assertEqual(self.c.next_read().maximum, 9)
        self.assertEqual(sink.size, 1)
        self.c.abort()
        self.assert_unknown()

    def test_partial_outbound_and_interrupt_no_healthy_exit(self):
        self.begin()
        self.c.abort()
        self.assert_unknown()

    def test_empty_or_excessive_data_rejected(self):
        for raw in (b'', b'xx', bytearray(b'x')):
            with self.subTest(raw=raw):
                self.c = p.OfflineChannel('dummy', budget=self.budget)
                self.begin()
                self.c.feed(struct.pack('<IHH4B', 1, 0x40, 1, 0, 0, 0, 0))
                with self.assertRaises(ValueError): self.c.feed(raw)
                self.assert_unknown()

    def test_missing_drain_prevents_complete(self):
        self.begin()
        deliver(self.c, transcript(b'z' * 512)[:-1])
        self.assertTrue(self.c.active)
        self.assertIsNone(self.c.result)
        self.c.abort()
        self.assert_unknown()

    def test_extra_bytes_after_complete_never_start_next_reply(self):
        self.begin()
        deliver(self.c, transcript(b'x'))
        with self.assertRaises(RuntimeError): self.c.feed(b'extra')
        self.assert_unknown()

    def test_global_budget_accumulates_across_responses(self):
        self.budget.limit = 3
        self.begin()
        deliver(self.c, transcript(b'ab'))
        self.begin('saved')
        with self.assertRaises(ValueError): self.c.feed(struct.pack('<IHH4B', 2, 0x40, 2, 0, 0, 0, 0))
        self.assertEqual(self.budget.used, 2)
        self.assert_unknown()

    def test_status_prefix_split_at_every_byte(self):
        self.c.begin('select:cpapp-b.bin')
        deliver(self.c, transcript(bytes(4), fragments=1))
        self.assertEqual(self.budget.used, 0)
        self.assertEqual(self.c.selected, 'cpapp-b.bin')

    def test_drain_content_cannot_prove_frame_identity(self):
        # Upstream ignores drain bytes. Even header-shaped bytes are opaque,
        # so this parser cannot establish a real USB transfer's identity.
        c = p.OfflineChannel('dummy', budget=self.budget)
        spec = c.requests['ram']; c.begin('ram', Sink(spec.limit, budget=self.budget))
        deliver(c, transcript(b'z' * 512)[:-1])
        c.feed(struct.pack('<IHH4B', 1, 0x40, 1, 0, 0, 0, 0))
        self.assertFalse(c.active)
        self.assertEqual(c.result['payload']['bytes'], 512)
        self.assertFalse(c.result['physical_protocol_verified'])

    def test_final_sink_stored_and_read_back_with_protocol_payload_only(self):
        import tempfile
        from lutphoto.capturestore import Store
        with tempfile.TemporaryDirectory() as temp:
            folder = Path(temp).resolve() / 'new-capture'
            store = Store(folder)
            try:
                self.select()
                spec = self.c.requests['read:cpapp-b.bin']
                sink = Sink(spec.limit, exact=spec.exact, budget=self.budget,
                            store=store, relative='source/cpapp-b.bin')
                self.c.begin('read:cpapp-b.bin', sink)
                raw = b'Q' * 1024
                result = deliver(self.c, transcript(bytes(4) + raw, seq=2))
                self.assertEqual(store.read('source/cpapp-b.bin', result['payload']), raw)
            finally:
                store.close()

    def test_one_deadline_across_requests_and_fragments(self):
        self.select()
        original = self.budget.deadline
        self.clock[0] = 1199
        self.begin()
        self.assertEqual(self.c.next_read().timeout_ms, 1000)
        self.c.feed(struct.pack('<IHH4B', 2, 0x40, 2, 0, 0, 0, 0))
        self.c.feed(b'a')
        self.clock[0] = 1200
        with self.assertRaises(TimeoutError): self.c.next_read()
        self.assertEqual(original, self.budget.deadline)
        self.assert_unknown()

    def test_pre_send_expired_budget_no_wire(self):
        self.clock[0] = 1200
        with self.assertRaises(TimeoutError): self.begin()
        self.assertEqual(self.c.wire_bytes, 0)
        self.assertFalse(self.c.unknown)

    def test_sink_contract_wrong_budget_or_size_rejected(self):
        spec = self.c.requests['ram']
        sinks = [Sink(1, budget=self.budget), Sink(spec.limit, budget=Budget(100)),
                 Sink(spec.limit, exact=1, budget=self.budget)]
        closed = Sink(spec.limit, budget=self.budget); closed.close(); sinks.append(closed)
        for sink in sinks:
            c = p.OfflineChannel('dummy', budget=self.budget)
            with self.assertRaises(ValueError): c.begin('ram', sink)
            self.assertEqual(c.wire_bytes, 0)
            self.assertFalse(c.unknown)

    def test_sink_write_disk_full_or_keyboard_interrupt_is_unknown(self):
        for exc in (OSError('self-generated disk-full'), KeyboardInterrupt()):
            self.c = p.OfflineChannel('dummy', budget=self.budget)
            self.begin()
            self.c.feed(struct.pack('<IHH4B', 1, 0x40, 1, 0, 0, 0, 0))
            with patch.object(Sink, 'write', side_effect=exc):
                with self.assertRaises(type(exc)): self.c.feed(b'a')
            self.assert_unknown()

    def test_fsync_after_framing_error_is_known(self):
        self.begin()
        with patch.object(Sink, 'finish', side_effect=OSError('self-generated fsync failure')):
            with self.assertRaises(OSError): deliver(self.c, transcript(b'z' * 512))
        self.assertIsNone(self.c.result)
        self.assert_healthy_exit_once()

    def test_request_feed_and_sequence_exhaustion(self):
        for field, value in (('calls', p.MAX_REQUESTS), ('sequence', 0x10000)):
            c = p.OfflineChannel('dummy', budget=self.budget); setattr(c, field, value)
            with self.assertRaises(ValueError): c.begin('select:cpapp-b.bin')
            self.assertEqual(c.wire_bytes, 0)
        self.begin()
        self.c.feeds = p.MAX_FEEDS
        with self.assertRaises(ValueError): self.c.next_read()
        self.assert_unknown()

    def test_overlapping_request_cannot_replace_active_response(self):
        self.begin()
        with self.assertRaises(RuntimeError): self.begin('saved')
        self.assertTrue(self.c.active)
        self.c.abort()
        self.assert_unknown()

    def test_stdlib_import_without_device_stack(self):
        code = ('import sys; from lutphoto import captureprotocol; '
                'assert not any(n == "usb" or n.startswith("usb.") or n in '
                '("transport", "core", "macfl23.session", "numpy") for n in sys.modules)')
        result = subprocess.run([sys.executable, '-S', '-B', '-c', code],
            cwd=Path(__file__).resolve().parents[2], capture_output=True)
        self.assertEqual(result.returncode, 0, result.stderr)


if __name__ == '__main__':
    unittest.main()
